 "content": "def transform(grid):
    """Fill the gaps between same-row or same-column marker cells with 3."""
    h, w = len(grid), len(grid[0])
    marker = max(max(row) for row in grid)
    out = [row[:] for row in grid]
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == marker]
        if len(cols) >= 2:
            for c in range(min(cols) + 1, max(cols)):
